package com.luckyalanzhou.barcodegenerator

/** 浏览器端传输页拆分为结构、样式、行为三个明确模板，避免服务端拼接替换。 */
internal object LanShareWebTemplates {
    fun page() = buildString {
        append(documentHead())
        append(styles())
        append(documentBody())
        append(script())
        append("</body></html>")
    }

    private fun documentHead() = """<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>文件传输</title>"""

    private fun styles() = """<style>
:root{color-scheme:light dark;--bg:#f4f6fb;--panel:#fff;--text:#172033;--line:#d9e0ea;--sub:#667085}@media(prefers-color-scheme:dark){:root{--bg:#000;--panel:#1d1d1f;--text:#f5f5f7;--line:#333;--sub:#8e8e93}}*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,sans-serif;margin:0;color:var(--text);background:var(--bg)}main{max-width:560px;margin:auto;min-height:100vh;padding-bottom:86px}.bar{display:flex;align-items:center;justify-content:space-between;padding:18px 20px 12px;font-size:20px;font-weight:700}.connection-status{font-size:13px;font-weight:500;color:var(--sub);white-space:nowrap}.connection-status.connected{color:#22c55e}ul{display:flex;flex-direction:column;align-items:flex-start;gap:10px;padding:0 14px;margin:0}li{display:flex;align-items:center;gap:12px;width:fit-content;max-width:78%;padding:10px 14px;border:1px solid rgba(255,255,255,.72);border-radius:18px;list-style:none;background:rgba(255,255,255,.62);box-shadow:0 10px 28px rgba(31,41,55,.08),inset 0 1px rgba(255,255,255,.8);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}li.mine{align-self:flex-end;background:rgba(10,132,255,.58);border-color:rgba(147,197,253,.58)}li.peer{align-self:flex-start}.image-item{flex-direction:column;align-items:flex-start;padding:6px;gap:8px}.media-preview{width:auto;max-width:100%;height:auto;max-height:260px;object-fit:contain;align-self:center;border-radius:12px;background:rgba(0,0,0,.08)}li:not(.image-item)::before{content:'📎';font-size:22px}li a:first-of-type{min-width:0;flex:1;overflow-wrap:anywhere;color:var(--text)}small{display:block;color:var(--sub);margin-top:4px}.download{padding:8px 13px;border:1px solid var(--line);border-radius:999px;color:#0a84ff;text-decoration:none}.bottom{position:fixed;bottom:0;left:0;right:0;background:var(--panel);padding:14px}.bottom form{display:flex;align-items:center;gap:8px;max-width:560px;margin:auto}.file-picker,.send-button{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border:1px solid var(--line);border-radius:22px;cursor:pointer;flex:0 0 44px}.message-input{min-width:0;flex:1;height:44px;padding:0 14px;border:1px solid var(--line);border-radius:22px;background:transparent;color:var(--text);font:inherit}.send-button{background:#0a84ff;color:white}.attachment-sheet{display:none;position:fixed;width:154px;padding:6px;border:1px solid var(--line);border-radius:20px;background:var(--panel);box-shadow:0 16px 40px rgba(31,41,55,.2);z-index:10}.attachment-sheet.open{display:flex;flex-direction:column}.attachment-sheet button{width:100%;min-height:38px;border:0;border-top:1px solid rgba(71,91,122,.2);background:transparent;color:var(--text);font:inherit}.attachment-sheet button:first-child{border-top:0}
</style></head>"""

    private fun documentBody() = """<body><main><div class="bar"><span>文件传输</span><span id="connection-status" class="connection-status">○ 正在连接设备...</span></div><ul id="files"></ul><div class="bottom"><form id="upload-form"><button type="button" class="file-picker" id="attachment-button" aria-label="添加附件">📎</button><input id="camera-capture" type="file" accept="image/*" capture="environment" hidden><input id="gallery" type="file" accept="image/*" hidden><input id="file-picker" type="file" hidden><input id="message" class="message-input" placeholder="输入文字" autocomplete="off"><button type="submit" class="send-button" aria-label="发送或上传">↑</button></form></div><div id="attachment-sheet" class="attachment-sheet"><button data-picker="camera-capture">拍摄图片</button><button data-picker="gallery">照片图库</button><button data-picker="file-picker">选择文件</button><button class="sheet-close">取消</button></div></main>"""

    private fun script() = """<script>
const files=document.getElementById('files'),form=document.getElementById('upload-form'),message=document.getElementById('message'),status=document.getElementById('connection-status'),sheet=document.getElementById('attachment-sheet'),attachmentButton=document.getElementById('attachment-button');const idKey='lanShareClientId';let clientId=localStorage.getItem(idKey);if(!clientId){clientId='c'+Date.now().toString(36)+Math.random().toString(36).slice(2,10);localStorage.setItem(idKey,clientId)}function image(name){return /\.(jpg|jpeg|png|gif|webp|heic|heif)/i.test(name||'')}function size(n){return n>=1048576?(n/1048576).toFixed(1)+' MB':Math.floor(n/1024)+' KB'}function state(ok){status.textContent=ok?'● 已连接到设备':'○ 正在连接设备...';status.classList.toggle('connected',ok)}function existing(id){return Array.from(files.children).some(x=>x.dataset.fileId===id)}function item(file,url){const li=document.createElement('li');li.dataset.fileId=file.id||'';li.className=file.sender==='browser:'+clientId?'mine':'peer';if(image(file.name)){const img=document.createElement('img');img.src=url;img.className='media-preview';img.alt=file.name;li.classList.add('image-item');li.append(img)}const link=document.createElement('a');link.href=url;link.download='';link.textContent=file.name||'未命名';const small=document.createElement('small');small.textContent=size(file.size||0);li.append(link,small);if(!image(file.name)){const download=document.createElement('a');download.href=url;download.download='';download.className='download';download.textContent='下载';li.append(download)}li.onclick=e=>{if(!e.target.closest('a'))link.click()};return li}function append(file){if(file.id&&existing(file.id))return;files.append(item(file,'/api/download/'+encodeURIComponent(file.id)))}function refresh(){fetch('/api/files?_='+Date.now(),{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(list=>list.forEach(append)).catch(()=>state(false))}function upload(file){fetch('/upload?name='+encodeURIComponent(file.name||'消息.txt')+'&client='+encodeURIComponent(clientId),{method:'PUT',headers:{'content-type':file.type||'application/octet-stream'},body:file}).then(r=>{if(!r.ok)throw Error();message.value='';refresh()}).catch(()=>alert('发送失败，请刷新页面后重试'))}form.onsubmit=e=>{e.preventDefault();const text=message.value.trim();if(text)upload(new File([text],'消息.txt',{type:'text/plain'}));else message.focus()};attachmentButton.onclick=()=>{sheet.classList.add('open');const r=attachmentButton.getBoundingClientRect();sheet.style.left=(r.left+8)+'px';sheet.style.top=(r.top-sheet.offsetHeight-16)+'px'};['camera-capture','gallery','file-picker'].forEach(id=>document.getElementById(id).onchange=e=>{const file=e.target.files[0];if(file){sheet.classList.remove('open');upload(file)}e.target.value='' });sheet.onclick=e=>{const id=e.target.dataset.picker;if(id)document.getElementById(id).click();if(e.target.classList.contains('sheet-close'))sheet.classList.remove('open')};function heartbeat(){fetch('/api/presence?_='+Date.now(),{cache:'no-store'}).then(r=>state(r.ok)).catch(()=>state(false))}let socket;function connect(){try{socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws');socket.onopen=()=>{state(true);socket.send('sync')};socket.onmessage=e=>{try{const p=JSON.parse(e.data);if(p.type==='snapshot')p.files.forEach(append);else if(p.file)append(p.file);else refresh()}catch(_){}};socket.onclose=()=>{state(false);setTimeout(connect,1000)}}catch(_){setTimeout(connect,1000)}}heartbeat();refresh();setInterval(heartbeat,2000);setInterval(refresh,5000);connect();
</script>"""
}
